import { GoogleGenAI } from "@google/genai";

/**
 * Simple in-memory cache to prevent redundant calls and handle 429s gracefully
 */
const responseCache: Record<string, string> = {
  priority: "",
  admin: ""
};

/**
 * Helper to call Gemini with exponential backoff for transient errors
 */
async function generateWithRetry(model: string, prompt: string, cacheKey: string, fallback: string, retries = 2, delay = 1000): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        temperature: 0.7,
        topP: 0.9,
      }
    });

    const text = response.text;
    if (text) {
      responseCache[cacheKey] = text;
      return text;
    }
    return responseCache[cacheKey] || fallback;
  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("429") || errorMessage.includes("quota")) {
      if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
        return generateWithRetry(model, prompt, cacheKey, fallback, retries - 1, delay * 2);
      }
      return responseCache[cacheKey] || fallback;
    }
    console.error(`Gemini API Error (${cacheKey}):`, error);
    return responseCache[cacheKey] || fallback;
  }
}

export const getPriorityInsights = async (history: any[], userName: string) => {
  const prompt = `
    Context: A Medical Representative (MR) named ${userName} is using a hospital pass booking system.
    System Rules:
    - 14 days without a pass: +5 priority points.
    - 7 days without a pass: +3 priority points.
    - Pass in last 3 days: -5 priority points (Cool-down period).
    - Missed entry (no-show): -10 points.

    User Recent History: ${JSON.stringify(history)}

    Task: Write a 2-sentence encouraging insight for ${userName}. 
    Explain their current standing and give one tip to improve their chances in the next lottery.
    Tone: Professional, supportive, and clear.
  `;

  const defaultFallback = "Your priority is calculated based on recent visits to ensure fairness. Regular participation helps maintain a steady rank.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "priority", defaultFallback);
};

export const getAdminBriefing = async (apps: any[], passes: any[], hospitalName: string) => {
  const prompt = `
    Context: You are an AI analyst for ${hospitalName}. 
    Today's Data: 
    - Total Applications: ${apps.length}
    - Passes Issued: ${passes.length}
    - Success Rate: ${apps.length > 0 ? ((passes.length / apps.length) * 100).toFixed(1) : 0}%

    Task: Provide a one-sentence high-level summary of today's demand and a specific recommendation for tomorrow's pass limits to optimize traffic flow.
    Tone: Analytical and concise.
  `;

  const defaultFallback = "Demand is currently stable. Maintain existing pass limits to balance MR access with hospital operations.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "admin", defaultFallback);
};

import React, { useState, useContext, useRef, useEffect } from 'react';
import { ShieldCheck, Search, QrCode, User, CheckCircle, XCircle, Camera, X, RefreshCw, Smartphone } from 'lucide-react';
import { storageService } from '../services/storageService';
import { IssuedPass, MedicalRep } from '../types';
import { FeedbackContext } from '../App';

const SecurityView: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [passId, setPassId] = useState('');
  const [scannedPass, setScannedPass] = useState<IssuedPass | null>(null);
  const [mrDetails, setMrDetails] = useState<MedicalRep | null>(null);
  const [error, setError] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
      setIsScanning(true);
      setError('');
    } catch (err) {
      console.error("Camera access error:", err);
      showFeedback("Could not access camera. Check permissions.", "error");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setIsScanning(false);
  };

  const handleVerify = (idToVerify?: string) => {
    const id = (idToVerify || passId).trim().toUpperCase();
    if (!id) return;

    setError('');
    const passes = storageService.getPasses();
    // Support searching by either the generated ID or the QR code string
    const pass = passes.find(p => p.id === id || p.qrCode === id || p.id === `PASS-${id}`);

    if (!pass) {
      setError("Pass not found or invalid identifier.");
      setScannedPass(null);
      setMrDetails(null);
      return;
    }

    const today = new Date().toISOString().split('T')[0];
    if (pass.passDate !== today) {
      setError(`Pass is for another date: ${pass.passDate}`);
      setScannedPass(null);
      setMrDetails(null);
      return;
    }

    if (pass.entryStatus === 'entered') {
      setError("Pass already used for entry today.");
      setScannedPass(null);
      setMrDetails(null);
      return;
    }

    if (pass.entryStatus === 'expired') {
      setError("Pass has expired.");
      setScannedPass(null);
      setMrDetails(null);
      return;
    }

    const mr = storageService.getMRs().find(m => m.id === pass.mrId);
    setScannedPass(pass);
    setMrDetails(mr || null);
    showFeedback("Pass Verified. Cross-check Identity Card.");
  };

  const confirmEntry = () => {
    if (!scannedPass) return;

    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === scannedPass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: scannedPass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Security-Main-Gate'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    showFeedback(`Access Granted: ${mrDetails?.fullName}`, 'success');
    setScannedPass(null);
    setMrDetails(null);
    setPassId('');
  };

  const reset = () => {
    setScannedPass(null);
    setMrDetails(null);
    setPassId('');
    setError('');
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <section className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-8 opacity-5">
           <ShieldCheck className="h-32 w-32 text-indigo-900" />
        </div>

        <div className="text-center relative z-10">
          <div className="bg-indigo-600 p-4 rounded-3xl w-fit mx-auto mb-6 shadow-lg shadow-indigo-200">
            <ShieldCheck className="h-8 w-8 text-white" />
          </div>
          <h3 className="text-3xl font-black text-slate-800 mb-2 tracking-tight">Gate Entry Control</h3>
          <p className="text-slate-500 font-medium mb-10">Scan MR credential or enter ID manually</p>

          {!isScanning ? (
            <div className="space-y-6">
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="relative flex-1 group">
                  <input 
                    type="text" 
                    value={passId}
                    onChange={(e) => setPassId(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleVerify()}
                    placeholder="Enter Pass ID (e.g. PASS-XYZ)"
                    className="w-full pl-12 pr-4 py-5 bg-slate-50 border-2 border-slate-100 rounded-3xl focus:border-indigo-500 focus:bg-white transition-all font-mono font-bold text-lg outline-none"
                  />
                  <QrCode className="absolute left-4 top-1/2 -translate-y-1/2 h-6 w-6 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
                </div>
                <button 
                  onClick={() => handleVerify()}
                  className="bg-indigo-600 text-white px-8 py-5 rounded-3xl font-black hover:bg-indigo-700 active:scale-95 transition-all shadow-xl shadow-indigo-100 flex items-center justify-center gap-2"
                >
                  <Search className="h-5 w-5" />
                  VERIFY
                </button>
              </div>

              <div className="relative py-4">
                 <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-100"></div></div>
                 <div className="relative flex justify-center text-xs font-black uppercase tracking-widest text-slate-400 bg-white px-4 w-fit mx-auto">OR USE SCANNER</div>
              </div>

              <button 
                onClick={startCamera}
                className="w-full py-5 border-2 border-indigo-100 rounded-3xl flex items-center justify-center gap-3 text-indigo-600 font-black hover:bg-indigo-50 hover:border-indigo-300 transition-all"
              >
                <Camera className="h-6 w-6" />
                OPEN CAMERA SCANNER
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in zoom-in-95 duration-300">
              <div className="relative aspect-square sm:aspect-video w-full max-w-md mx-auto bg-slate-900 rounded-[2rem] overflow-hidden border-4 border-slate-800 shadow-2xl">
                <video 
                  ref={videoRef} 
                  autoPlay 
                  playsInline 
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
                  <div className="w-full h-full border-2 border-indigo-400/50 rounded-xl relative">
                    <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                    <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500"></div>
                    <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500"></div>
                    <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                    <div className="absolute top-1/2 left-0 w-full h-0.5 bg-indigo-500/30 animate-pulse"></div>
                  </div>
                </div>
                <button 
                  onClick={stopCamera}
                  className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 backdrop-blur-md p-2 rounded-full text-white transition-all"
                >
                  <X className="h-6 w-6" />
                </button>
              </div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Center the QR code within the frame</p>
            </div>
          )}
        </div>
      </section>

      {error && (
        <div className="bg-red-50 border border-red-100 p-6 rounded-3xl flex items-center gap-4 text-red-700 animate-in slide-in-from-top-4">
          <XCircle className="h-8 w-8 shrink-0" />
          <div>
            <p className="font-black uppercase text-xs tracking-widest mb-1">Verification Failed</p>
            <p className="font-bold text-sm">{error}</p>
          </div>
        </div>
      )}

      {scannedPass && mrDetails && (
        <div className="bg-white rounded-[2.5rem] shadow-2xl border border-indigo-100 overflow-hidden animate-in slide-in-from-bottom-8 duration-500">
          <div className="bg-indigo-600 p-8 text-white flex justify-between items-center">
            <div className="flex items-center gap-4">
               <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-md">
                 <Smartphone className="h-6 w-6" />
               </div>
               <div>
                  <h4 className="text-xl font-black tracking-tight">Access Token Valid</h4>
                  <p className="text-indigo-100 text-xs font-bold uppercase tracking-widest">ID: {scannedPass.id}</p>
               </div>
            </div>
            <button onClick={reset} className="p-2 hover:bg-white/10 rounded-full transition-all"><X className="h-6 w-6" /></button>
          </div>

          <div className="p-8 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Visitor Identity</label>
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                       <p className="text-2xl font-black text-slate-800">{mrDetails.fullName}</p>
                       <p className="text-indigo-600 font-bold text-sm">{mrDetails.companyName}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                     <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <label className="text-[10px] font-black text-slate-400 uppercase block mb-1">Session</label>
                        <p className="font-black text-slate-800">{scannedPass.session}</p>
                     </div>
                     <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <label className="text-[10px] font-black text-slate-400 uppercase block mb-1">Time Slot</label>
                        <p className="font-black text-slate-800">{scannedPass.timeSlot}</p>
                     </div>
                  </div>

                  <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl">
                     <div className="flex items-center gap-2 mb-2">
                        <ShieldCheck className="h-4 w-4 text-amber-500" />
                        <p className="text-[10px] font-black text-amber-700 uppercase">Verification Procedure</p>
                     </div>
                     <p className="text-xs font-bold text-amber-900">Compare the photo ID on the right with the physical visitor. Ensure the SLCPI ID matches: <span className="underline">{mrDetails.slcpiId || 'NOT SET'}</span></p>
                  </div>
               </div>

               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Official Credentials Photo</label>
                  {mrDetails.slcpiPhoto ? (
                    <div className="rounded-3xl overflow-hidden border-4 border-white shadow-xl bg-slate-100 aspect-[4/3] flex items-center justify-center">
                       <img src={mrDetails.slcpiPhoto} alt="SLCPI" className="w-full h-full object-contain" />
                    </div>
                  ) : (
                    <div className="aspect-[4/3] bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center text-slate-300">
                       <User className="h-12 w-12 mb-2" />
                       <p className="text-xs font-bold">No photo on record</p>
                    </div>
                  )}
               </div>
            </div>

            <div className="flex gap-4 pt-4 border-t border-slate-100">
               <button 
                 onClick={reset}
                 className="flex-1 py-5 border-2 border-slate-100 text-slate-400 font-black rounded-3xl hover:bg-slate-50 transition-all uppercase tracking-widest text-xs"
               >
                 CANCEL
               </button>
               <button 
                 onClick={confirmEntry}
                 className="flex-[2] py-5 bg-green-600 text-white font-black rounded-3xl shadow-xl shadow-green-100 hover:bg-green-700 active:scale-95 transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
               >
                 <CheckCircle className="h-5 w-5" />
                 CONFIRM & LOG ENTRY
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SecurityView;

import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
                const currentUser = storageService.getCurrentUser();
                if (currentUser?.hospitalId === hosp.id && currentUser.role === 'ADMIN') {
                  showFeedback(`Scheduled lottery for ${sess} executed automatically!`, 'success');
                }
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Login User ID' : 'Login ID / Mobile'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "e.g. john_mr" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white/10 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20">
                <HospitalIcon className="h-3.5 w-3.5 text-indigo-100" />
                <span className="text-xs font-black text-white tracking-tighter">MedPass Technology</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-indigo-200 uppercase tracking-widest opacity-60">Enterprise Compliance Grid</p>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user!} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user?.role === 'SUPER_ADMIN' ? 'Root Authority' : user?.role === 'MR' ? 'MR Dashboard' : `${user?.fullName} Panel`}
      >
        {user?.role === 'MR' && <MRDashboard user={user as any} />}
        {user?.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user?.role === 'ADMIN' && <AdminDashboard user={user as any} />}
        {user?.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user?.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

