            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>SESSIONS & AUTO-SPIN</button>
