                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official Name</label>
                    <input type="text" value={editingHospital.name} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Facility Address</label>
                    <textarea 
                      value={editingHospital.address || ''} 
