                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Public Mobile</label>
                      <input 
                        type="tel" 
                        value={editingHospital.mobileNumber || ''} 
                        onChange={(e) => setEditingHospital({...editingHospital, mobileNumber: e.target.value})}
