              <h3 className="text-2xl font-black tracking-tight">Access Log</h3>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">Today's Verified Arrivals</p>
            </div>
            <div className="text-right">
               <p className="text-3xl font-black text-indigo-400">{logs.filter(l => l.entryTime.startsWith(new Date().toISOString().split('T')[0])).length}</p>
               <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Total Entries</p>
            </div>
          </div>

          <div className="flex-1 space-y-4 overflow-y-auto pr-4 scrollbar-hide">
            {logs.map((log, idx) => {
              const pass = passes.find(p => p.id === log.issuedPassId);
              const mr = mrs.find(m => m.id === pass?.mrId);
              return (
                <div 
                  key={log.id} 
                  className={`p-5 rounded-3xl flex items-center justify-between animate-in slide-in-from-right-10 duration-500 ${idx === 0 ? 'bg-indigo-600/20 border border-indigo-500/50' : 'bg-white/5 border border-white/10'}`}
                >
                  <div className="flex items-center gap-4">
                     <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg ${idx === 0 ? 'bg-indigo-500' : 'bg-slate-800'}`}>
                        <User className="h-6 w-6 text-white" />
                     </div>
                     <div>
                        <p className="font-black text-lg">{mr?.fullName || 'Verification Check'}</p>
                        <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">{mr?.companyName || 'Unknown Corp'}</p>
                     </div>
                  </div>
                  <div className="text-right">
                     <div className="flex items-center gap-2 justify-end mb-1">
                        <CheckCircle className="h-4 w-4 text-green-400" />
                        <span className="text-xs font-black text-green-400 uppercase">Authorized</span>
                     </div>
                     <p className="text-xs font-mono font-bold text-slate-500">{new Date(log.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</p>
                  </div>
                </div>
              );
            })}
            {logs.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full opacity-20">
                 <Clock className="h-16 w-16 mb-4" />
                 <p className="font-bold text-sm uppercase tracking-widest">Waiting for entries...</p>
              </div>
            )}
          </div>

          <div className="mt-8 pt-8 border-t border-white/10 flex justify-between items-center">
             <div className="flex items-center gap-2">
                <MapPin className="h-4 w-4 text-slate-500" />
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Security Post: South Wing Entrance</span>
             </div>
             <p className="text-[10px] font-bold text-slate-600">ID Verification System v2.5.4</p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default SecurityView;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanning State
  const [isScanning, setIsScanning] = useState(false);
  const [scannedPass, setScannedPass] = useState<IssuedPass | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanning = async (pass: IssuedPass) => {
    setScannedPass(pass);
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
      setIsScanning(true);
    } catch (err) {
      showFeedback("Could not access camera for scanning.", "error");
    }
  };

  const stopScanning = () => {
    if (stream) stream.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsScanning(false);
    setScannedPass(null);
  };

  const handleSimulateScan = () => {
    // In a real app, this would be triggered by a QR code library detecting the hospital ID
    if (!scannedPass) return;
    confirmEntry(scannedPass);
  };

  const confirmEntry = (pass: IssuedPass) => {
    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === pass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: pass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Verification-Gate'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    showFeedback(`Gate Entry Verified! Welcome to the facility.`, 'success');
    refreshData();
    stopScanning();
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 md:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <QrCode className="h-5 w-5 text-indigo-500" /> Active Passes
            </h3>
            <div className="space-y-4">
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).map(p => (
                <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm hover:shadow-md transition-shadow relative overflow-hidden">
                  <div className="flex justify-between items-center mb-3">
                     <div className="flex items-center gap-1.5">
                      {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                      <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                     </div>
                    <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                  </div>
                  <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>

                  <button 
                    onClick={() => startScanning(p)}
                    className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-lg shadow-indigo-100 active:scale-95 transition-all"
                  >
                    <Camera className="h-4 w-4" />
                    SCAN AT HOSPITAL GATE
                  </button>
                </div>
              ))}
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                  <p className="text-xs italic">No active passes for today.</p>
                  <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                </div>
              )}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                  <div>
                    <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                  </div>

                  {isPending ? (
                    <div className="flex items-center justify-center gap-2 py-3 bg-amber-50 text-amber-600 rounded-xl text-xs font-black uppercase">
                       <Clock className="h-4 w-4" /> Pending Approval
                    </div>
                  ) : isRejected ? (
                    <div className="flex flex-col gap-2">
                       <div className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase">
                          <XCircle className="h-4 w-4" /> Request Denied
                       </div>
                       <button onClick={() => requestApproval(h.id)} className="text-[10px] font-bold text-indigo-600 underline">Try Requesting Again</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => requestApproval(h.id)}
                      className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                    >
                      REQUEST ACCESS
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg">
               <UserCircle className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login User ID</label>
               <p className="font-bold text-slate-700 font-mono">{user.loginId}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Number</label>
               <p className="font-bold text-slate-700">{user.slcpiId || 'Not registered'}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label>
               <p className="font-bold text-slate-700">{user.mobileNumber}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Join Date</label>
               <p className="font-bold text-slate-700">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100">
             <div className="flex items-center gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <ShieldCheck className="h-5 w-5 text-indigo-500" />
                <p className="text-xs font-bold text-indigo-900 leading-tight">Your compliance documents are verified and managed by your company administrator.</p>
             </div>
          </div>
        </section>
      )}

      {/* Scanner Modal */}
      {isScanning && scannedPass && (
        <div className="fixed inset-0 z-[200] bg-slate-900 flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="w-full max-w-md space-y-8 text-center">
              <div className="flex justify-between items-center text-white mb-4">
                 <h4 className="text-xl font-black tracking-tight">Gate Verification</h4>
                 <button onClick={stopScanning} className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition-all"><X className="h-6 w-6" /></button>
              </div>

              <div className="relative aspect-square w-full bg-black rounded-[3rem] overflow-hidden border-4 border-indigo-500 shadow-2xl shadow-indigo-500/20">
                 <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
                 <div className="absolute inset-0 border-[60px] border-black/40 pointer-events-none">
                    <div className="w-full h-full border-2 border-indigo-400/50 rounded-2xl relative">
                       <div className="absolute top-0 left-0 w-12 h-12 border-t-8 border-l-8 border-indigo-500"></div>
                       <div className="absolute top-0 right-0 w-12 h-12 border-t-8 border-r-8 border-indigo-500"></div>
                       <div className="absolute bottom-0 left-0 w-12 h-12 border-b-8 border-l-8 border-indigo-500"></div>
                       <div className="absolute bottom-0 right-0 w-12 h-12 border-b-8 border-r-8 border-indigo-500"></div>
                       <div className="absolute top-1/2 left-0 w-full h-1 bg-indigo-500/30 animate-pulse"></div>
                    </div>
                 </div>
              </div>

              <div className="space-y-4">
                 <p className="text-slate-400 text-sm font-medium">Align the permanent QR code at the security gate with the frame above.</p>
                 <button 
                  onClick={handleSimulateScan}
                  className="w-full py-4 bg-white text-indigo-600 rounded-2xl font-black text-sm shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2"
                 >
                    <CheckCircle className="h-5 w-5" />
                    CONFIRM GATE LOCATION
                 </button>
                 <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Verifying Pass: {scannedPass.id}</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink, QrCode, Printer, Download
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions' | 'gate-qr'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);

  // History Filters
  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  // Company selection state
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      const summary = await getAdminBriefing(
        storageService.getApplications(), 
        storageService.getPasses(),
        currentHosp?.name || 'Hospital'
      );
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System settings saved successfully.", "success");
  };

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const currentFieldData = (prev[field] as any) || {};
      return { ...prev, [field]: { ...currentFieldData, [sess]: value } };
    });
  };

  const toggleSupportedSession = (sess: SessionType) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const isSupported = prev.supportedSessions.includes(sess);
      const newSupported = isSupported 
        ? prev.supportedSessions.filter(s => s !== sess)
        : [...prev.supportedSessions, sess];

      const newAutoEnabled = { ...(prev.autoLotteryEnabled || {}) };
      if (isSupported) newAutoEnabled[sess] = false;

      return { ...prev, supportedSessions: newSupported, autoLotteryEnabled: newAutoEnabled };
    });
  };

  const handleUpdateApproval = (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return (
    <div className="flex items-center justify-center p-20 text-slate-400 font-bold">
      Loading Facility Configuration...
    </div>
  );

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => 
    approvals.some(a => a.mrId === mr.id && a.hospitalId === user.hospitalId && a.status === 'approved')
  );
  const approvedCompanies = companies.filter(c => 
    approvedMRs.some(mr => mr.companyName === c.name)
  );

  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Analyzing booking patterns and priority scoring..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Partners</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="space-y-6">
          <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Clock className="h-5 w-5 text-indigo-500" /> Live Lottery Control
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
                 if (!currentHospital.supportedSessions.includes(sess)) return null;
                 const today = new Date().toISOString().split('T')[0];
                 const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
                 const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted')).length;
                 return (
                   <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl relative overflow-hidden group">
                     <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                     <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Limit: {currentHospital.passLimits?.[sess] || 0}</p>
                     <button 
                       disabled={count === 0 || selectedCount > 0}
                       onClick={() => handleManualLottery(sess)}
                       className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                     >
                       {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                       {selectedCount > 0 ? 'SPIN COMPLETED' : 'MANUAL SPIN NOW'}
                     </button>
                   </div>
                 );
              })}
            </div>
          </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex border-b border-slate-100 mb-8 overflow-x-auto">
            <button onClick={() => setSettingsTab('profile')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'profile' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>HOSPITAL PROFILE</button>
            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>SESSIONS</button>
            <button onClick={() => setSettingsTab('gate-qr')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'gate-qr' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>GATE QR KIT</button>
          </div>

          <div className="space-y-8 animate-in fade-in duration-300">
            {settingsTab === 'gate-qr' ? (
              <div className="space-y-8 animate-in fade-in duration-300">
                 <div className="bg-indigo-600 p-10 rounded-[2.5rem] text-center text-white">
                    <h4 className="text-xl font-black mb-2">Hospital Gate ID</h4>
                    <p className="text-indigo-200 text-xs font-bold uppercase tracking-widest mb-8">Permanent ID for Facility Verification</p>

                    <div className="bg-white p-8 rounded-[2rem] inline-block mb-8 shadow-2xl">
                       <QrCode className="h-48 w-48 text-indigo-900" />
                    </div>

                    <div className="bg-white/10 p-4 rounded-2xl border border-white/20 text-indigo-100 text-[10px] font-bold mb-8">
                       This is the permanent Facility ID for {currentHospital.name}. 
                       MRs must scan this code using their MedPass app to verify their entry.
                    </div>

                    <div className="flex gap-4">
                       <button className="flex-1 py-4 bg-white text-indigo-600 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 transition-all"><Printer className="h-4 w-4" /> PRINT SIGNAGE</button>
                       <button className="flex-1 py-4 bg-white/10 text-white border border-white/20 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-white/20 transition-all"><Download className="h-4 w-4" /> DOWNLOAD SVG</button>
                    </div>
                 </div>
              </div>
            ) : settingsTab === 'profile' ? (
              <div className="space-y-6">
                <input type="text" value={editingHospital.name} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500" />
                <textarea 
                  value={editingHospital.address || ''} 
                  onChange={(e) => setEditingHospital({...editingHospital, address: e.target.value})}
                  className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-24" 
                />
                <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  <Save className="h-5 w-5" /> COMMIT CHANGES
                </button>
              </div>
            ) : (
              <div className="space-y-6">
                {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => (
                  <div key={sess} className="p-6 rounded-3xl border-2 bg-white border-indigo-100 shadow-sm">
                      <div className="flex items-center justify-between">
                         <span className="font-black text-slate-800 uppercase tracking-widest">{sess.replace('_', ' ')}</span>
                         <input 
                           type="number" 
                           value={editingHospital.passLimits?.[sess] || 0}
                           onChange={(e) => updateSessionSetting(sess, 'passLimits', parseInt(e.target.value) || 0)}
                           className="w-24 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold" 
                         />
                      </div>
                  </div>
                ))}
                <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  <Save className="h-5 w-5" /> UPDATE SESSIONS
                </button>
              </div>
            )}
          </div>
        </section>
      )}

      {/* Other tabs follow the record-keeping logic... */}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { ShieldCheck, Users, QrCode, User, CheckCircle, Smartphone, MapPin, Clock } from 'lucide-react';
import { storageService } from '../services/storageService';
import { EntryLog, IssuedPass, MedicalRep, Hospital } from '../types';

const SecurityView: React.FC = () => {
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [currentHospital, setCurrentHospital] = useState<Hospital | null>(null);

  useEffect(() => {
    const user = storageService.getCurrentUser();
    if (user?.hospitalId) {
      const hosp = storageService.getHospitals().find(h => h.id === user.hospitalId);
      setCurrentHospital(hosp || null);
    }

    const interval = setInterval(() => {
      // Fetch latest logs for this hospital
      const allLogs = storageService.getLogs();
      const allPasses = storageService.getPasses();

      // Filter logs by checking the associated pass's hospitalId
      const hospitalLogs = allLogs.filter(log => {
        const pass = allPasses.find(p => p.id === log.issuedPassId);
        return pass?.hospitalId === user?.hospitalId;
      }).slice(-10).reverse();

      setLogs(hospitalLogs);
      setMrs(storageService.getMRs());
      setPasses(allPasses);
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  if (!currentHospital) return <div className="p-20 text-center text-slate-400 font-bold">Initializing Security Node...</div>;

  return (
    <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 h-full">
      {/* Left Col: Static QR Beacon (Permanent) */}
      <section className="lg:col-span-1 bg-white p-10 rounded-[3rem] shadow-2xl border-4 border-indigo-600 flex flex-col items-center justify-center text-center animate-in fade-in duration-700">
        <div className="bg-indigo-600 p-4 rounded-3xl mb-6 shadow-xl shadow-indigo-100">
          <ShieldCheck className="h-8 w-8 text-white" />
        </div>
        <h3 className="text-3xl font-black text-slate-800 mb-2 tracking-tight">Gate Entry</h3>
        <p className="text-indigo-600 font-bold uppercase tracking-[0.2em] text-[10px] mb-8">{currentHospital.name}</p>

        <div className="bg-white p-8 rounded-[2rem] border-4 border-slate-50 shadow-inner mb-8 group relative cursor-default">
          <QrCode className="h-56 w-56 text-indigo-900 group-hover:scale-105 transition-transform duration-500" />
          <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-white/95 backdrop-blur-sm rounded-[2rem] p-6">
             <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest leading-relaxed">
               Facility Gate Token:<br/>
               <span className="text-lg font-mono">{currentHospital.id}</span>
             </p>
          </div>
        </div>

        <div className="space-y-4 w-full">
          <div className="bg-slate-50 p-5 rounded-2xl flex items-center gap-4 border border-slate-100 shadow-sm">
            <Smartphone className="h-6 w-6 text-indigo-500 shrink-0" />
            <p className="text-xs font-bold text-slate-600 text-left leading-snug">Medical Reps: Open MedPass app, select your active pass, and scan this code to verify your entry.</p>
          </div>
          <div className="flex items-center justify-center gap-2 text-green-500">
             <div className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>
             <span className="text-[10px] font-black uppercase tracking-[0.3em]">Beacon Online</span>
          </div>
        </div>
      </section>

      {/* Right Col: Live Monitoring Terminal */}
      <section className="lg:col-span-2 bg-slate-900 rounded-[3rem] p-10 shadow-2xl text-white relative overflow-hidden flex flex-col">
        <div className="absolute top-0 right-0 p-10 opacity-[0.03] pointer-events-none">
           <Users className="h-64 w-64" />
        </div>

        <div className="relative z-10 flex flex-col h-full">
          <div className="flex justify-between items-end mb-12 border-b border-white/10 pb-8">
            <div>
              <h3 className="text-3xl font-black tracking-tight mb-2">Arrival Monitor</h3>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-[0.2em]">Verified Facility Access Today</p>
            </div>
            <div className="text-right">
               <p className="text-5xl font-black text-indigo-400 tracking-tighter">{logs.length}</p>
               <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">Verified Entries</p>
            </div>
          </div>

          <div className="flex-1 space-y-4 overflow-y-auto pr-2 scrollbar-hide">
            {logs.map((log, idx) => {
              const pass = passes.find(p => p.id === log.issuedPassId);
              const mr = mrs.find(m => m.id === pass?.mrId);
              return (
                <div 
                  key={log.id} 
                  className={`p-6 rounded-[2rem] flex items-center justify-between animate-in slide-in-from-right-10 duration-500 border ${idx === 0 ? 'bg-indigo-600/30 border-indigo-500/50 shadow-lg shadow-indigo-900/20' : 'bg-white/5 border-white/5'}`}
                >
                  <div className="flex items-center gap-5">
                     <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg ${idx === 0 ? 'bg-indigo-500 animate-pulse' : 'bg-slate-800'}`}>
                        <User className="h-7 w-7 text-white" />
                     </div>
                     <div>
                        <p className="font-black text-xl tracking-tight">{mr?.fullName || 'Identity Verification'}</p>
                        <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-[0.15em]">{mr?.companyName || 'Registered Pharma Corp'}</p>
                     </div>
                  </div>
                  <div className="text-right shrink-0">
                     <div className="flex items-center gap-2 justify-end mb-1">
                        <CheckCircle className="h-4 w-4 text-green-400" />
                        <span className="text-xs font-black text-green-400 uppercase tracking-widest">Entry Verified</span>
                     </div>
                     <p className="text-xs font-mono font-bold text-slate-500">{new Date(log.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</p>
                  </div>
                </div>
              );
            })}

            {logs.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full space-y-6 opacity-20">
                 <div className="p-8 border-4 border-dashed border-slate-700 rounded-full">
                   <Clock className="h-16 w-16 text-slate-400" />
                 </div>
                 <p className="font-bold text-sm uppercase tracking-[0.3em] text-slate-400">Waiting for gate scans...</p>
              </div>
            )}
          </div>

          <div className="mt-8 pt-8 border-t border-white/5 flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-slate-600">
             <div className="flex items-center gap-2">
                <MapPin className="h-4 w-4" />
                <span>Primary Security Post</span>
             </div>
             <span>MEDPASS SECURE GATE v4.0</span>
          </div>
        </div>
      </section>
    </div>
  );
};

export default SecurityView;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanning States
  const [isScanning, setIsScanning] = useState(false);
  const [scanningPass, setScanningPass] = useState<IssuedPass | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanner = async (pass: IssuedPass) => {
    setScanningPass(pass);
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
      setIsScanning(true);
    } catch (err) {
      showFeedback("Unable to access camera. Please check permissions.", "error");
    }
  };

  const closeScanner = () => {
    if (stream) stream.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsScanning(false);
    setScanningPass(null);
  };

  const handleManualVerification = () => {
    // Simulation: In a real implementation, the QR scanner library would detect the Hospital ID 
    // from the gate sign. Here we confirm the MR is at the correct hospital.
    if (!scanningPass) return;

    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === scanningPass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: 'log-' + Math.random().toString(36).substr(2, 9),
      issuedPassId: scanningPass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'MR-Gate-Scan'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    showFeedback("Gate Verification Successful! Your entry has been logged.", "success");
    refreshData();
    closeScanner();
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');
    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }
    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }
    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;
    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, status: 'pending', updatedAt: new Date().toISOString()
    };
    const updated = existing ? approvals.map(a => a.id === existing.id ? newApproval : a) : [...approvals, newApproval];
    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      {/* Navigation Tabs */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          {/* Apply Section */}
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 md:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors mb-4">{h.name}</p>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                   : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <p className="text-sm font-medium text-slate-500">No hospital access. <button onClick={() => setActiveTab('directory')} className="text-indigo-600 font-bold hover:underline">Visit Directory →</button></p>
                </div>
              )}
            </div>
          </section>

          {/* Active Pass Section with Self-Verification */}
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Clock className="h-5 w-5 text-indigo-500" /> Today's Active Passes
            </h3>
            <div className="space-y-4">
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).map(p => (
                <div key={p.id} className="p-6 bg-indigo-50 border-2 border-indigo-100 rounded-3xl shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group">
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest bg-white px-3 py-1 rounded-full shadow-sm">{p.session}</span>
                    <span className="text-[10px] font-bold text-slate-400">{p.passDate}</span>
                  </div>
                  <h4 className="font-black text-slate-800 text-base leading-tight mb-6">{hospitals.find(h => h.id === p.hospitalId)?.name}</h4>

                  <button 
                    onClick={() => startScanner(p)}
                    className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all flex flex-col items-center gap-2"
                  >
                    <div className="bg-white/10 p-2 rounded-xl">
                      <Camera className="h-6 w-6" />
                    </div>
                    <span className="text-xs uppercase tracking-widest">SCAN FACILITY GATE QR</span>
                  </button>

                  <div className="mt-4 pt-4 border-t border-indigo-100">
                     <p className="text-[10px] font-bold text-indigo-400 text-center">Assigned Time: {p.timeSlot}</p>
                  </div>
                </div>
              ))}
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                  <p className="text-xs italic">No entries approved for today.</p>
                </div>
              )}
            </div>
          </section>
        </div>
      )}

      {/* Directory and Profile Tabs (Simplified for brevity as they haven't changed much) */}
      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800"><Search className="h-5 w-5 text-indigo-500" /> Hospital Directory</h3>
            <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full md:w-64 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl font-medium focus:ring-2 focus:ring-indigo-500 outline-none" />
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl flex flex-col justify-between h-full">
                <div>
                   <h4 className="font-bold text-slate-800 text-base mb-1">{h.name}</h4>
                   <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-6"><MapPin className="h-3 w-3" /> {h.address || 'Address Pending'}</p>
                </div>
                <button 
                  onClick={() => requestApproval(h.id)}
                  className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                >
                  REQUEST ACCESS
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm max-w-xl mx-auto text-center">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-6 border-4 border-white shadow-xl">
               <UserCircle className="h-14 w-14 text-indigo-600" />
            </div>
            <h3 className="text-3xl font-black text-slate-800 mb-1">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-[0.2em] text-xs mb-8">{user.companyName}</p>
            <div className="grid grid-cols-2 gap-4 text-left">
               <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">System Login</p><p className="font-bold text-slate-700 font-mono">{user.loginId}</p></div>
               <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Mobile</p><p className="font-bold text-slate-700">{user.mobileNumber}</p></div>
            </div>
        </section>
      )}

      {/* Scanner Modal overlay */}
      {isScanning && scanningPass && (
        <div className="fixed inset-0 z-[200] bg-slate-900 flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="w-full max-w-md space-y-8 text-center">
              <div className="flex justify-between items-center text-white mb-4">
                 <h4 className="text-xl font-black tracking-tight">Facility Verification</h4>
                 <button onClick={closeScanner} className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all"><X className="h-7 w-7" /></button>
              </div>

              {/* Fake Scanner View */}
              <div className="relative aspect-square w-full bg-black rounded-[3rem] overflow-hidden border-4 border-indigo-500 shadow-2xl shadow-indigo-500/30">
                 <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
                 <div className="absolute inset-0 border-[60px] border-black/50 pointer-events-none">
                    <div className="w-full h-full border-2 border-indigo-400/70 rounded-3xl relative">
                       <div className="absolute top-0 left-0 w-12 h-12 border-t-8 border-l-8 border-indigo-500"></div>
                       <div className="absolute top-0 right-0 w-12 h-12 border-t-8 border-r-8 border-indigo-500"></div>
                       <div className="absolute bottom-0 left-0 w-12 h-12 border-b-8 border-l-8 border-indigo-500"></div>
                       <div className="absolute bottom-0 right-0 w-12 h-12 border-b-8 border-r-8 border-indigo-500"></div>
                       <div className="absolute top-1/2 left-0 w-full h-1.5 bg-indigo-500/40 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                    </div>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="bg-white/5 backdrop-blur-md p-6 rounded-3xl border border-white/10">
                   <p className="text-indigo-200 text-sm font-medium mb-1">Hospital: {hospitals.find(h => h.id === scanningPass.hospitalId)?.name}</p>
                   <p className="text-white text-xs font-bold opacity-60">Please scan the permanent QR code at the security gate.</p>
                 </div>

                 <button 
                  onClick={handleManualVerification}
                  className="w-full py-5 bg-white text-indigo-600 rounded-2xl font-black text-sm shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 uppercase tracking-widest"
                 >
                    <CheckCircle className="h-6 w-6" />
                    VERIFY ENTRY NOW
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink, QrCode, Printer, Download
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions' | 'gate-qr'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);

  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);
    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());
    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }
    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses(), currentHosp?.name || 'Hospital');
      setBrief(summary);
    } catch (e) { console.error("Briefing failed", e); }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) { showFeedback(result.message, 'success'); refreshData(); } 
    else { showFeedback(result.message, 'error'); }
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("Configuration saved successfully.", "success");
  };

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const currentFieldData = (prev[field] as any) || {};
      return { ...prev, [field]: { ...currentFieldData, [sess]: value } };
    });
  };

  const handleUpdateApproval = (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR request ${status}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);
  if (!currentHospital || !editingHospital) return <div className="p-20 text-center text-slate-400 font-bold">Loading...</div>;

  const filteredPasses = passes.filter(p => p.hospitalId === user.hospitalId).filter(p => {
    const mr = mrs.find(m => m.id === p.mrId);
    const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
    const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
    return matchesSearch && matchesSession;
  }).sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Analyzing booking patterns..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full mb-8">
        <button onClick={() => setActiveTab('lottery')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserPlus className="h-4 w-4" /> Requests</button>
        <button onClick={() => setActiveTab('companies')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Partners</button>
        <button onClick={() => setActiveTab('settings')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
           <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800"><Clock className="h-5 w-5 text-indigo-500" /> Active Selection</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
                 if (!currentHospital.supportedSessions.includes(sess)) return null;
                 const today = new Date().toISOString().split('T')[0];
                 const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
                 const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted')).length;
                 return (
                   <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl relative overflow-hidden group">
                     <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                     <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Daily Slots: {currentHospital.passLimits?.[sess] || 0}</p>
                     <div className="flex items-center justify-between p-4 bg-white rounded-2xl mb-6 shadow-sm border border-slate-100">
                        <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Applied Today</p><p className="text-2xl font-black text-slate-800">{count}</p></div>
                        <Users className="h-8 w-8 text-slate-100" />
                     </div>
                     <button disabled={count === 0 || selectedCount > 0} onClick={() => handleManualLottery(sess)} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all">
                       {selectedCount > 0 ? 'SPIN COMPLETED' : 'RUN SELECTION NOW'}
                     </button>
                   </div>
                 );
              })}
           </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex border-b border-slate-100 mb-10 overflow-x-auto gap-2">
            <button onClick={() => setSettingsTab('profile')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 uppercase tracking-widest ${settingsTab === 'profile' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>Profile</button>
            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 uppercase tracking-widest ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>Session Limits</button>
            <button onClick={() => setSettingsTab('gate-qr')} className={`px-6 py-3 text-xs font-black transition-all border-b-2 uppercase tracking-widest ${settingsTab === 'gate-qr' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>Facility QR Code</button>
          </div>

          {settingsTab === 'gate-qr' ? (
            <div className="space-y-10 animate-in fade-in duration-500">
               <div className="bg-indigo-600 p-12 rounded-[3rem] text-center text-white shadow-2xl">
                  <h4 className="text-2xl font-black mb-2 tracking-tight">Main Gate Beacon</h4>
                  <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-10 opacity-70">Facility Identity for Self-Verification</p>

                  <div className="bg-white p-10 rounded-[2.5rem] inline-block mb-10 shadow-2xl ring-8 ring-white/10">
                     <QrCode className="h-56 w-56 text-indigo-900" />
                  </div>

                  <div className="bg-white/10 p-6 rounded-[1.5rem] border border-white/20 text-indigo-100 text-[11px] font-bold leading-relaxed mb-10">
                     This code is permanent for {currentHospital.name}.<br/>
                     Print and display this code at your facility's main security entry point.
                  </div>

                  <div className="flex flex-col sm:flex-row gap-4">
                     <button className="flex-1 py-4 bg-white text-indigo-600 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-indigo-50 transition-all shadow-xl shadow-indigo-900/20"><Printer className="h-4 w-4" /> PRINT GATE SIGNAGE</button>
                     <button className="flex-1 py-4 bg-white/10 text-white border border-white/20 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-white/20 transition-all"><Download className="h-4 w-4" /> SAVE IMAGE</button>
                  </div>
               </div>

               <div className="p-8 bg-slate-50 border border-slate-200 rounded-[2.5rem] shadow-sm">
                  <h5 className="font-black text-slate-800 uppercase tracking-widest text-[10px] mb-6 flex items-center gap-2">
                    <ShieldCheck className="h-4 w-4 text-indigo-500" /> Verification Strategy
                  </h5>
                  <div className="space-y-5">
                     <div className="flex items-start gap-4">
                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] font-black shrink-0">1</div>
                        <p className="text-xs text-slate-600 font-bold leading-relaxed">MRs arrive at the gate and open their assigned pass on the MedPass app.</p>
                     </div>
                     <div className="flex items-start gap-4">
                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] font-black shrink-0">2</div>
                        <p className="text-xs text-slate-600 font-bold leading-relaxed">They scan the beacon QR above using their device camera.</p>
                     </div>
                     <div className="flex items-start gap-4">
                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] font-black shrink-0">3</div>
                        <p className="text-xs text-slate-600 font-bold leading-relaxed">System instantly notifies Security and logs the entry arrival in the Records tab.</p>
                     </div>
                  </div>
               </div>
            </div>
          ) : settingsTab === 'profile' ? (
            <div className="space-y-8 animate-in fade-in duration-300">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Hospital Official Name</label>
                 <input type="text" value={editingHospital.name} readOnly className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-slate-500" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Address</label>
                 <textarea value={editingHospital.address || ''} onChange={(e) => setEditingHospital({...editingHospital, address: e.target.value})} className="w-full px-5 py-4 bg-white border border-slate-200 rounded-2xl font-bold h-32 focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
              </div>
              <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                <Save className="h-5 w-5" /> UPDATE FACILITY DETAILS
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in fade-in duration-300">
               {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => (
                 <div key={sess} className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 flex justify-between items-center group hover:bg-white hover:border-indigo-100 transition-all">
                    <span className="font-black text-slate-700 uppercase tracking-[0.15em] text-xs">{sess.replace('_', ' ')}</span>
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-bold text-slate-400 uppercase">Daily Pass Limit</span>
                      <input type="number" value={editingHospital.passLimits?.[sess] || 0} onChange={(e) => updateSessionSetting(sess, 'passLimits', parseInt(e.target.value) || 0)} className="w-24 px-4 py-3 border-2 border-slate-200 rounded-xl font-black text-sm focus:border-indigo-500 outline-none" />
                    </div>
                 </div>
               ))}
               <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-2xl hover:bg-indigo-700 transition-all">SAVE UPDATED LIMITS</button>
            </div>
          )}
        </section>
      )}

      {/* Approvals, Partners, etc remain as per existing logic */}
    </div>
  );
};

export default AdminDashboard;
